refentry.refsect1:
&reftitle.description;
public arraynullYaf_Controller_Abstract::getInvokeArgs
Devuelve todos los argumentos de invocación de la acción actual, como un array indexado por el nombre del argumento. Los argumentos de invocación se pasan a la acción mediante Yaf_Controller_Abstract::forward.

  &reftitle.examples;

   Ejemplo de Yaf_Controller_Abstract::getInvokeArgs


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function indexAction() {
        $this->forward("list", array("category" => "book", "page" => 2));
        return false; // ends the current flow
    }

    public function listAction() {
        // todos los argumentos de invocación de la acción actual
        var_dump($this->getInvokeArgs());
    }
}
?>


   &example.outputs.similar;


array(2) {
  ["category"]=>
  string(4) "book"
  ["page"]=>
  int(2)
}
